// Process Timeline Data - RAW 데이터 그대로 전달 (변형 없음)
const items = $input.all();

return items.map(item => {
  const output = item.json.output;

  // RAW 데이터 그대로 전달 - 변형 없음
  return {
    json: output // 원본 데이터 그대로
  };
}).filter(item => item !== null);

// Combined Node - Timeline ID 추출 + RAW 데이터 처리                                       
  const input = $input.all()[0].json;
  const rows = $input.all();
  const targetData = $('Random').first().json;

  // Timeline ID 추출                                                                         
  const TimelineFile = input.files?.find(f => f.name === "Timeline");
  const timeline_id = TimelineFile?.id;

  if (rows.length === 0) {
    return [{ json: { error: "No data received" } }];
  }

  // 랜덤 선택                                                                                
  const randomIndex = Math.floor(Math.random() * rows.length);
  const selectedRow = rows[randomIndex].json;

  // RAW 데이터 추출                                                                          
  let rawData;
  try {
    if (selectedRow.raw_data) {
      rawData = JSON.parse(selectedRow.raw_data);
    } else {
      rawData = selectedRow;
    }
  } catch (error) {
    rawData = selectedRow;
  }

  // Timeline ID와 채널 메타데이터 추가                                                       
  const payload = {
    ...rawData, // 원본 데이터 그대로                                                         
    timeline_id: timeline_id, // Timeline ID 추가                                             
    channel_config: {
      voice_preference: targetData.voice_preference,
      veo3_priority: targetData.veo3_priority,
      channel_type: targetData.channel_type,
      channel_name: targetData.channel_name
    },
    webhook_url: "http://172.27.86.48:5678/webhook/video-complete",          timestamp: new Date().toISOString()
  };

  console.log(`API 전달: ${payload.title} (${payload.format_type}) - Timeline ID:             
  ${timeline_id}`);

  return [{ json: payload }];

// Channel Data에서 설정 받아서 매핑
const input = $input.first().json;
const channelType = input.channel_type || "korean_business";

console.log(`선택된 채널 타입: ${channelType}`);

const channelSettings = {
  "ATT": {
    language: "english", 
    voice: "pNInz6obpgDQGcFmaJgB",
    style: "professional",
    name: "ATT",
    veo3Priority: true,
    description: "CGXR"
  }
};

const selectedChannel = channelSettings[channelType];

if (!selectedChannel) {
  throw new Error(`Unknown channel type: ${channelType}`);
}

return [{
  json: {
    channel_type: channelType,
    channel_config: selectedChannel,
    target_language: selectedChannel.language,
    voice_preference: selectedChannel.voice,
    content_style: selectedChannel.style,
    channel_name: selectedChannel.name,
    veo3_priority: selectedChannel.veo3Priority,
    description: selectedChannel.description,
    timestamp: new Date().toISOString()
  }
}];

// 시간대 기반 스마트 카테고리 선택 + 채널 설정 적용
const hour = new Date().getHours();
const day = new Date().getDay();

// Channel Mapper에서 설정 받아오기
const channelData = $('Channel Mapper').first().json;
const targetLanguage = channelData.target_language;
const voicePreference = channelData.voice_preference;
const contentStyle = channelData.content_style;
const channelName = channelData.channel_name;
const veo3Priority = channelData.veo3_priority;
const channelType = channelData.channel_type;

console.log('선택된 채널: ' + channelName + ' (' + targetLanguage + ')');

// 수익성 검증된 카테고리 (시간대별)
const timeCategories = {
  "morning": ["Business Success (비즈니스 성공)", "Productivity Tips (생산성 팁)"],
  "afternoon": ["Life Hacks (생활 꿀팁)", "Health Tips (건강 정보)"],
  "evening": ["Wellness (웰빙)", "Relationships (인간관계)"],
  "night": ["Science Facts (과학 상식)", "Learning Methods (학습법)"]
};

// 시간대 결정
let timeSlot;
if (hour >= 6 && hour < 12) timeSlot = "morning";
else if (hour >= 12 && hour < 18) timeSlot = "afternoon";
else if (hour >= 18 && hour < 22) timeSlot = "evening";
else timeSlot = "night";

// 주말 보정
if (day === 0 || day === 6) {
  timeSlot = "afternoon"; // 주말엔 라이프스타일 중심
}

const availableCategories = timeCategories[timeSlot];
const selectedCategory = availableCategories[Math.floor(Math.random() * availableCategories.length)];

// 콘텐츠 형식 랜덤 선택 (timeline vs storyboard)
const formatTypes = ["timeline"];
// const formatTypes = ["timeline", "storyboard"];

const selectedFormat = formatTypes[Math.floor(Math.random() * formatTypes.length)];

console.log('선택된 형식: ' + selectedFormat + ', 카테고리: ' + selectedCategory);

return [{
  json: {
    format_type: selectedFormat,
    selected_category: selectedCategory,
    target_language: targetLanguage,
    voice_preference: voicePreference,
    content_style: contentStyle,
    channel_name: channelName,
    channel_type: channelType,
    veo3_priority: veo3Priority,
    time_slot: timeSlot,
    hour: hour,
    is_weekend: day === 0 || day === 6,
    optimization_hint: timeSlot + '_' + targetLanguage + '_' + contentStyle + '_' + selectedFormat,
    timestamp: new Date().toISOString()
  }
}];

// Scene Config Generator - LLM 입력 전 설정 생성 + 강화된 디버깅
const input = $input.first().json;

// 🎛️ 사용자 조정 가능한 설정 (여기서 쉽게 수정 가능)
const USER_CONFIG = {
  // 기본 설정
  target_duration: 20,        // 원하는 총 길이 (초)
  scenes_count: 2,           // 원하는 장면 수 (3-7)

  // VEO 제약사항
  veo2_duration_range: [5, 8],     // VEO 2 지원 범위
  veo3_duration_options: [4, 6, 8], // VEO 3 지원 옵션
  force_veo3_compliance: true,     // VEO3 제약 강제 적용

  // 품질 설정
  min_scene_duration: 2,     // 최소 장면 길이
  prefer_even_distribution: true, // 균등 분배 선호

  // 채널별 오버라이드 (선택사항)
  channel_overrides: {
    'korean_business': { scenes_count: 3, target_duration: 15 },
    'english_global': { scenes_count: 6, target_duration: 30 },
    'japanese_premium': { scenes_count: 4, target_duration: 24 },
    'chinese_volume': { scenes_count: 5, target_duration: 25 },
    'spanish_latino': { scenes_count: 5, target_duration: 25 }
  }
};

// 🔧 Helper Functions
function adjustDurationForVeo(duration, forceVeo3 = true) {
  if (forceVeo3) {
    // VEO3: 4, 6, 8초만 지원
    if (duration <= 4) return 4;
    if (duration <= 6) return 6;
    return 8;
  } else {
    // VEO2: 5-8초 지원
    return Math.min(Math.max(duration, 5), 8);
  }
}

function generateOptimalDurations(sceneCount, totalDuration, config) {
  const avgDuration = totalDuration / sceneCount;
  const durations = [];

  for (let i = 0; i < sceneCount; i++) {
    let duration = avgDuration;

    // VEO 제약사항 적용
    duration = adjustDurationForVeo(duration, config.force_veo3_compliance);
    durations.push(duration);
  }

  // 총 길이 맞추기 위한 미세 조정
  const totalGenerated = durations.reduce((sum, d) => sum + d, 0);
  if (totalGenerated !== totalDuration) {
    // 첫 번째 씬에 차이를 반영 (VEO 제약 내에서)
    const diff = totalDuration - totalGenerated;
    const adjustedFirst = durations[0] + diff;
    durations[0] = adjustDurationForVeo(adjustedFirst, config.force_veo3_compliance);
  }

  return durations;
}

// 🚀 Main Processing
try {
  // 🔍 DEBUGGING: 입력 데이터 확인
  console.log('=== SCENE CONFIG GENERATOR DEBUG ===');
  console.log('1. Input received:', JSON.stringify(input, null, 2));

  // Random 노드에서 채널 설정 받아오기
  const channelType = input.channel_type || 'korean_business';
  console.log('2. Channel type detected:', channelType);

  // 채널별 설정 오버라이드 적용
  const config = channelType && USER_CONFIG.channel_overrides[channelType] 
    ? { ...USER_CONFIG, ...USER_CONFIG.channel_overrides[channelType] }
    : USER_CONFIG;

  console.log('3. Applied config:', JSON.stringify(config, null, 2));

  // 최적 duration 배열 생성
  const optimalDurations = generateOptimalDurations(
    config.scenes_count, 
    config.target_duration, 
    config
  );

  console.log('4. Generated durations:', optimalDurations);
  console.log('5. Total duration check:', optimalDurations.reduce((a,b) => a+b, 0));

  // LLM에 전달할 설정 생성
  const sceneConfig = {
    // Random 노드 데이터 유지
    ...input,

    // 새로운 씬 설정 추가
    target_scenes_count: config.scenes_count,
    target_total_duration: config.target_duration,
    individual_scene_durations: optimalDurations,
    veo3_compliance: config.force_veo3_compliance,

    // LLM 프롬프트용 지시사항
    llm_instructions: {
      scenes_instruction: `Generate exactly ${config.scenes_count} scenes/shots`,
      duration_instruction: `Each scene duration: ${optimalDurations.join('s, ')}s respectively`,
      total_duration_instruction: `Total video duration: ${config.target_duration} seconds`,
      format_instruction: input.format_type === 'timeline' ? 'Use timeline format' : 'Use storyboard format'
    },

    // 메타데이터
    config_generated_at: new Date().toISOString(),
    user_config_applied: config,
    debug_info: {
      original_channel: channelType,
      scenes_changed_from_default: config.scenes_count !== USER_CONFIG.scenes_count,
      duration_changed_from_default: config.target_duration !== USER_CONFIG.target_duration
    }
  };

  console.log('6. ✅ FINAL OUTPUT TO LLM:');
  console.log('   - Scenes:', config.scenes_count);
  console.log('   - Total duration:', config.target_duration);
  console.log('   - Individual durations:', optimalDurations.join(', '));
  console.log('   - Channel:', channelType);
  console.log('=== END DEBUG ===');

  return [{ json: sceneConfig }];

} catch (error) {
  console.error('❌ Error generating scene config:', error);
  // 에러 시 기본 설정으로 폴백
  return [{ 
    json: {
      ...input,
      target_scenes_count: 3,
      target_total_duration: 15,
      individual_scene_durations: [6, 6, 4],
      error: error.message,
      fallback_applied: true
    }
  }];
}
